# ============================================================
# app.py | THE CHAT SCREEN (Streamlit)
# ============================================================
#
# Run it from this folder:   streamlit run app.py
# It opens in your browser at http://localhost:8501
#
#   LEFT SIDEBAR → what is connected, what the agent may do, guardrail tester
#   MAIN AREA    → chat with your database in plain English
#                  + "SQL the agent ran" under every answer, with the real rows
#                  + Approve / Reject cards when the agent proposes a change
#
# You do NOT edit this file. Use .env and knowledge.md.
# ============================================================

import pandas as pd
import streamlit as st

import agent
import database
import settings

st.set_page_config(page_title="QueryDost", page_icon="🗄️", layout="wide")


# ------------------------------------------------------------
# Memory for THIS browser tab
# st.session_state → a dictionary that survives Streamlit re-runs
#   chat    → messages: {"role": "user"/"assistant", "content": "...", "queries": [...]}
#   notes   → this tab's notebook the tools write into: {"queries": [...], "pending": [...]}
#   pending → changes waiting for a human
# ------------------------------------------------------------
if "chat" not in st.session_state:
    st.session_state.chat = []
if "notes" not in st.session_state:
    st.session_state.notes = {"queries": [], "pending": []}
if "pending" not in st.session_state:
    st.session_state.pending = []


# ------------------------------------------------------------
# Connect and build the agent once per tab. If the database cannot be
# reached, say so clearly instead of showing a long Python error.
# ------------------------------------------------------------
if "agent" not in st.session_state:
    try:
        with st.spinner("Connecting and reading the database structure..."):
            st.session_state.tables = database.list_tables()
            st.session_state.agent = agent.build_agent(st.session_state.notes)
    except Exception as error:
        st.error("Could not start QueryDost.\n\n**Database:** " + database.get_safe_url()
                 + "\n\n**Model:** " + settings.LLM_MODEL + "\n\n**Problem:** " + str(error))
        st.info("Check DATABASE_URL, LLM_MODEL and your API key in the .env file, then refresh this page.")
        st.stop()


# ============================================================
# SIDEBAR
# ============================================================
st.sidebar.header("🔌 Connection")
st.sidebar.write("**Database:** " + database.get_dialect_name())
st.sidebar.caption(database.get_safe_url())
st.sidebar.write("**Model:** " + settings.LLM_MODEL)
tables = st.session_state.tables
mode = database.get_schema_mode()
st.sidebar.write("**Tables found:** " + str(len(tables)) + "  (mode: " + mode + ")")
with st.sidebar.expander("Show table names"):
    st.write(", ".join(tables))

st.sidebar.header("🛡️ What the agent may do")
if database.get_backend() == "sqlite":
    st.sidebar.success("Reads only: the file is opened READ-ONLY 🔒")
else:
    st.sidebar.success("Reads run in a transaction that is always rolled back 🔒")
    st.sidebar.caption("The real lock is your database login. Use a read-only user.")

if not settings.ALLOW_DB_CHANGES:
    st.sidebar.info("Data changes: ❌ off")
else:
    st.sidebar.warning("Data changes: ✋ proposed only, a human must approve "
                       "(" + ", ".join(settings.ALLOWED_CHANGE_TYPES) + ")")

st.sidebar.write("Python SQL check: " + ("✅ on" if settings.CHECK_SQL_IN_CODE else "❌ off"))
st.sidebar.write("Max rows per query: " + str(settings.MAX_ROWS))

# Reload after editing knowledge.md or changing the database structure
if st.sidebar.button("🔄 Reload knowledge.md and tables"):
    database.clear_cache()
    del st.session_state["agent"]
    st.rerun()


# ------------------------------------------------------------
# GUARDRAIL TESTER: run SQL directly with the agent's login, no model involved.
# Proves that the database itself refuses writes.
# ------------------------------------------------------------
st.sidebar.header("🧪 Guardrail tester")
st.sidebar.caption("Runs SQL directly with the agent's login. No model involved.")
first_table = tables[0] if len(tables) > 0 else "some_table"
test_sql = st.sidebar.text_area("SQL to try", "DELETE FROM " + first_table)
skip_check = st.sidebar.checkbox("Switch off the Python check (test the database's own lock)")
if st.sidebar.button("Run as the agent"):
    test_result = database.run_read_query(test_sql, skip_code_check=skip_check)
    if test_result["ok"]:
        st.sidebar.success("Query ran. Rows returned: " + str(len(test_result["rows"])))
    else:
        st.sidebar.error(test_result["error"])


# ============================================================
# MAIN AREA
# ============================================================
st.title("🗄️ " + settings.APP_TITLE)
st.caption("Plain English in. The agent writes the SQL, runs it read-only, and answers. "
           "Every query it ran is shown under the answer.")


# Show "SQL the agent ran" with the real rows, under an answer
def show_queries(queries):
    if len(queries) == 0:
        return
    with st.expander("🔍 SQL the agent ran (" + str(len(queries)) + ")"):
        for i in range(len(queries)):
            one_query = queries[i]
            st.code(one_query["sql"], language="sql")
            if one_query["result"]["ok"]:
                table = pd.DataFrame(one_query["result"]["rows"], columns=one_query["result"]["columns"])
                st.dataframe(table, hide_index=True)
            else:
                st.error(one_query["result"]["error"])


# The conversation so far
for i in range(len(st.session_state.chat)):
    message = st.session_state.chat[i]
    with st.chat_message(message["role"]):
        st.markdown(message["content"])
        show_queries(message["queries"])


# ============================================================
# HUMAN IN THE LOOP: Approve / Reject cards
# ============================================================
# Nothing touches the database until a human clicks Approve.
# Approve → runs with the APPROVER login (a different login from the agent's)
# Reject  → nothing changes, the decision is logged
for i in range(len(st.session_state.pending)):
    change = st.session_state.pending[i]
    st.warning("✋ **HUMAN APPROVAL NEEDED**\n\nThe agent wants to change the database. Reason: "
               + change["reason"])
    st.code(change["sql"], language="sql")
    approve_column, reject_column = st.columns(2)

    if approve_column.button("✅ Approve and save", key="approve_" + str(i)):
        try:
            rows_changed = database.run_approved_change(change["sql"])
            note = "✅ Approved by a human and saved. Rows changed: " + str(rows_changed)
        except Exception as error:
            note = "❌ The change was not saved: " + str(error)
        st.session_state.chat.append({"role": "assistant", "content": note, "queries": []})
        st.session_state.pending.pop(i)
        st.rerun()

    if reject_column.button("❌ Reject", key="reject_" + str(i)):
        database.write_audit("CHANGE REJECTED by human", change["sql"])
        note = "❌ Rejected by a human. Nothing was changed."
        st.session_state.chat.append({"role": "assistant", "content": note, "queries": []})
        st.session_state.pending.pop(i)
        st.rerun()


# ============================================================
# ASK A QUESTION
# ============================================================
question = st.chat_input("Ask anything about your data...")
if question:
    st.session_state.chat.append({"role": "user", "content": question, "queries": []})

    # Send the recent conversation so follow-up questions work.
    # Only the last HISTORY_MESSAGES messages, to keep the cost down.
    history = []
    start = max(0, len(st.session_state.chat) - settings.HISTORY_MESSAGES)
    for i in range(start, len(st.session_state.chat)):
        history.append((st.session_state.chat[i]["role"], st.session_state.chat[i]["content"]))
    # Some models (Claude) need the conversation to start with the user
    while len(history) > 1 and history[0][0] != "user":
        history.pop(0)

    notes = st.session_state.notes
    notes["queries"].clear()
    notes["pending"].clear()
    with st.spinner("Thinking and querying the database..."):
        try:
            response = st.session_state.agent.invoke({"messages": history})
            answer = response["messages"][-1].content
            # Some models return a list of parts instead of plain text
            if isinstance(answer, list):
                text_parts = []
                for p in range(len(answer)):
                    if isinstance(answer[p], dict) and answer[p].get("type") == "text":
                        text_parts.append(answer[p]["text"])
                answer = "\n".join(text_parts)
        except Exception as error:
            answer = "Something went wrong: " + str(error)

    st.session_state.chat.append({"role": "assistant", "content": answer,
                                  "queries": list(notes["queries"])})
    for i in range(len(notes["pending"])):
        st.session_state.pending.append(notes["pending"][i])
    st.rerun()
